const redis = new FakeRedis();
const M = '2026-07';
for (const [id, v] of [[1, 50], [2, 980], [3, 120], [4, 980], [5, 7], [6, 300]]) await redis.zadd('lb:notes:views:' + M, v, String(id));
redis.roundTrips = 0;
[await top(redis, M, 3), redis.roundTrips]

